1	/**
2	 * Контракт между платформой и играми. Имена фиксированы: на них опираются все игры.
3	 * Игра импортирует из платформы только `platform/sdk/*`.
4	 */
5	
6	/**
7	 * Генератор случайных чисел. `next()` возвращает число в [0, 1). Передаётся игре платформой.
8	 * На каждый вызов `start`/`action` игра получает отдельный замороженный объект; сохранять его между вызовами нельзя.
9	 */
10	export interface Rng {
11	  next(): number;
12	}
13	
14	/**
15	 * Результат шага игры.
16	 * - `continue` — раунд продолжается, нужен следующий ход;
17	 * - `finished` — раунд окончен, `payout` — полная сумма к зачислению (0 при проигрыше).
18	 */
19	export type Step<S> =
20	  | { status: 'continue'; state: S }
21	  | { status: 'finished'; state: S; payout: number };
22	
23	/**
24	 * Серверный модуль игры. Платформа вызывает его внутри раунда: списывает ставку до `start`
25	 * и зачисляет `payout` после шага со статусом `finished`. Игра не знает о кошельке и балансе.
26	 *
27	 * Состояние `S` и параметры `P` должны сериализоваться в JSON: платформа хранит их на диске.
28	 *
